// Decide which provider should handle the event based on CALENDAR_MODE and msg.calendarProvider
const mode = env.get('CALENDAR_MODE') || 'off';
msg.calendarProvider = msg.calendarProvider || mode;
if (msg.calendarProvider === 'off') {
    msg.calendarResult = { status: 'skipped', reason: 'calendar disabled' };
    return [null, msg];
}
return msg;

// Placeholder for CalDAV integration.
// Expect env CALDAV_URL, CALDAV_LOGIN, CALDAV_APP_PASSWORD.
// For now, emulate success and attach a reference UID.
msg.calendarResult = { provider: 'caldav', status: 'ok', ref: `caldav-${Date.now()}` };
return msg;

// Placeholder for Google Calendar API integration.
// Attach a synthetic reference to indicate success.
if (msg.calendarProvider === 'google') {
    msg.calendarResult = { provider: 'google', status: 'ok', ref: `gcal-${Date.now()}` };
}
return msg;

const allowList = (env.get('ALLOWLIST_CHAT_IDS') || '').split(',').map(s => s.trim()).filter(Boolean);
const adminIds = (env.get('ADMIN_TELEGRAM_IDS') || '').split(',').map(s => s.trim()).filter(Boolean);
const chatId = msg.chatId && msg.chatId.toString();
const isAllowed = allowList.length === 0 || allowList.includes(chatId);
if (!isAllowed) {
    return null;
}
const isGroup = msg.originalMessage && ['group', 'supergroup'].includes(msg.originalMessage.chat.type);
if (isGroup) {
    const botUsername = msg.originalMessage.botUsername || (env.get('BOT_USERNAME') || '').replace('@','');
    const mentioned = (msg.payload || '').includes(`@${botUsername}`);
    const isReply = !!msg.originalMessage.reply_to_message;
    if (!mentioned && !isReply) {
        return null;
    }
}
return msg;

let text = (msg.payload || '').trim();
const botUsername = env.get('BOT_USERNAME') || '';
if (botUsername) {
    const mention = new RegExp('\@' + botUsername.replace('@','') + '\b', 'i');
    text = text.replace(mention, '').trim();
}
msg.cleanText = text;
return msg;

// Context keyed by chat_id + user_id with expiry.
const key = `${msg.chatId}:${msg.from && msg.from.id}`;
const now = Date.now();
const stored = global.get(key) || {};
if (stored.expires_at && stored.expires_at < now) {
    global.set(key, {});
    msg.context = {}
} else {
    msg.context = stored;
}
msg.contextKey = key;
return msg;

// Merge user reply into stored draft and continue with pending action.
const ctx = msg.context || {};
msg.action = ctx.pending_action;
msg.entities = ctx.draft || {};
msg.entities.clarification_reply = msg.cleanText;
msg.fromClarification = true;
return msg;

msg.headers = { 'Content-Type': 'application/json' };
msg.payload = {
  contents: [{
    parts: [{
      text: `You are a planner bot. Output only JSON per schema. User text: ${msg.cleanText}`
    }]
  }],
  generationConfig: { temperature: 0 }
};
return msg;

const resp = msg.payload || {};
let text = ''
try {
    text = resp.candidates[0].content.parts[0].text;
} catch (e) {
    node.error('Gemini response invalid', msg);
    msg.action = 'unknown';
    return msg;
}
try {
    const parsed = JSON.parse(text);
    msg.action = parsed.action || 'unknown';
    msg.entities = parsed.entities || {};
    msg.need_clarification = parsed.need_clarification;
    msg.question = parsed.question;
} catch (e) {
    msg.action = 'unknown';
}
return msg;

const ctx = {
    pending_action: msg.entities && msg.entities.pending_action || msg.action_target || 'clarify',
    draft: msg.entities || {},
    expires_at: Date.now() + 30 * 60 * 1000
};
global.set(msg.contextKey, ctx);
msg.payload = msg.question || 'Нужны уточнения, уточните, пожалуйста.';
return msg;

const t = msg.entities.task || {};
msg.topic = 'insert task';
msg.params = [msg.chatId, t.title || msg.cleanText, t.details || null, 'open', msg.from.id, t.assignee || null, t.due_iso || null, t.remind_minutes || null, null, null, null, null];
msg.payload = {
    query: `INSERT INTO tasks (chat_id,title,details,status,created_by_user_id,assignee_user_id,due_at,remind_minutes,reminded_at,calendar_provider,calendar_ref,created_at,updated_at) VALUES (?,?,?,?,?,?,?,?,?,?,?,CURRENT_TIMESTAMP,CURRENT_TIMESTAMP);`,
    params: msg.params
};
return msg;

// Write audit log
msg.audit = { action: 'task_create', result: 'ok' };
return msg;

const calendar = msg.calendar || { status: 'not requested' };
msg.payload = `Задача создана
Название: ${msg.entities.task?.title || msg.cleanText}
Срок: ${msg.entities.task?.due_iso || '—'}
Исполнитель: ${msg.entities.task?.assignee || '—'}
Календарь: ${calendar.status || calendar.reason || '—'}`;
return msg;

const rows = msg.payload || [];
if (!rows.length) {
    msg.payload = 'Задач не найдено';
    return msg;
}
const lines = rows.map(r => `#${r.id} ${r.title} [${r.status}] ${r.due_at || ''}`);
msg.payload = lines.join('
');
return msg;

// Simplified update by last reference placeholder.
msg.payload = { query: `UPDATE tasks SET details=COALESCE(?,details), updated_at=CURRENT_TIMESTAMP WHERE chat_id=? ORDER BY updated_at DESC LIMIT 1;`, params: [msg.entities.task?.details || msg.cleanText, msg.chatId] };
return msg;

const e = msg.entities.event || {};
msg.payload = { query: `INSERT INTO events (chat_id,title,details,start_at,end_at,organizer_user_id,attendees_json,calendar_provider,calendar_ref,created_at,updated_at) VALUES (?,?,?,?,?,?,?,NULL,NULL,CURRENT_TIMESTAMP,CURRENT_TIMESTAMP);`, params: [msg.chatId, e.title || msg.cleanText, e.details || null, e.start_iso || null, e.end_iso || null, msg.from.id, JSON.stringify(e.attendees || [])] };
return msg;

const calendar = msg.calendar || { status: 'not requested' };
msg.payload = `Встреча создана
Название: ${msg.entities.event?.title || msg.cleanText}
Начало: ${msg.entities.event?.start_iso || '—'}
Календарь: ${calendar.status || calendar.reason || '—'}`;
return msg;

const rows = msg.payload || [];
if (!rows.length) { msg.payload = 'Нет задач'; return msg; }
msg.payload = rows.map(r => `${r.status}: ${r.c}`).join('
');
return msg;

const row = msg.payload;
msg.chatId = row.chat_id;
msg.payload = `Напоминание по задаче #${row.id}: ${row.title}
Срок: ${row.due_at}`;
msg.markReminder = row.id;
return msg;
